# main.py
# Fixed original melon agent.
# All token strings normalized to canonical no-space values.
# Task keys, crop tables, selling tables, and hiring logic corrected.

SAFE_MONEY_BUFFER = 200

# Labor / opening tunables
MAX_HANDS = 7
OPENING_HIRE_COUNT = 4
OPENING_MELON_SEEDS = 10

# Seed buying / planting tunables
SEED_BATCH_MELON = 4
MAX_NEW_PLANTS_PER_TURN = {
    "MELON": 5,
    "CARROT": 6,
    "WHEAT": 6,
}

# Land expansion
SECOND_LAND_ENABLED = False

# Selling / liquidation tunables
LIQUIDATION_DAY = 27
SHED_PRESSURE_LIMIT = 0.9


BASE_PRICE = {
    "WHEAT": 25,
    "CARROT": 35,
    "TOMATO": 60,
    "STRAWBERRY": 120,
    "MELON": 250,
    "EGG": 50,
    "MILK": 160,
    "WOOL": 200,
    "FERTILIZER": 100,
}

CROP_MAX_DAY = {
    "WHEAT": 4,
    "CARROT": 3,
    "MELON": 10,
}

CROP_MAX_YIELD = {
    "WHEAT": 4,
    "CARROT": 3,
    "MELON": 6,
}

ONGOING_CROPS = {"TOMATO", "STRAWBERRY"}

PREMIUM_ITEMS = {"STRAWBERRY", "MELON", "MILK", "WOOL"}

SELL_SAFE_INVENTORY = {
    "WHEAT": 10500,
    "CARROT": 10100,
    "TOMATO": 10050,
    "STRAWBERRY": 10020,
    "MELON": 10060,
    "EGG": 10300,
    "MILK": 10020,
    "WOOL": 10020,
    "FERTILIZER": 10200,
}

SELLABLE_ITEMS = [
    "WHEAT",
    "CARROT",
    "TOMATO",
    "STRAWBERRY",
    "MELON",
    "EGG",
    "MILK",
    "WOOL",
    "FERTILIZER",
]

SEED_COST = {
    "WHEAT": 10,
    "CARROT": 20,
    "MELON": 80,
}

MIN_PLANT_DAYS = {
    "WHEAT": 5,
    "CARROT": 4,
    "MELON": 11,
}

ZONE_PREFERENCE = [
    ["NW", "NE", "SW", "SE"],  # farmer
    ["NE", "NW", "SW", "SE"],  # hand 1
    ["SW", "NW", "NE", "SE"],  # hand 2
    ["SE", "SW", "NE", "NW"],  # hand 3
    ["NE", "SW", "NW", "SE"],  # hand 4
]


# -----------------------------
# Helpers
# -----------------------------

def _pass():
    return {"farmer": ["PASS"], "hands": [], "market": []}


def _safe_get(d, key, default):
    if isinstance(d, dict):
        return d.get(key, default)
    return default


def _int(value, default=0):
    try:
        if value is None:
            return default
        return int(value)
    except Exception:
        return default


def _float(value, default=0.0):
    try:
        if value is None:
            return default
        return float(value)
    except Exception:
        return default


def _is_sequence(obj):
    return isinstance(obj, (list, tuple))


def _in_bounds(tiles, x, y):
    try:
        return 0 <= y < len(tiles) and 0 <= x < len(tiles[y])
    except Exception:
        return False


def _step_towards(fx, fy, tx, ty):
    if tx < fx:
        return ["WEST"]
    if tx > fx:
        return ["EAST"]
    if ty < fy:
        return ["NORTH"]
    if ty > fy:
        return ["SOUTH"]
    return ["PASS"]


def _manhattan(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def _fib_cost(n):
    a, b = 1, 1
    for _ in range(max(0, n)):
        a, b = b, a + b
    return a


def _quadrant(x, y, tiles):
    half = max(1, len(tiles) // 2)
    if x < half and y < half:
        return "NW"
    if x >= half and y < half:
        return "NE"
    if x < half and y >= half:
        return "SW"
    return "SE"


def _is_plant(tile):
    return isinstance(tile, dict) and _safe_get(tile, "kind", "") == "PLANT"


def _is_weed(tile):
    return isinstance(tile, dict) and _safe_get(tile, "kind", "") == "WEED"


def _owned_counts(private):
    """
    Count shed + carried inventories.
    Seeds are excluded because they live in private["seeds"].
    """
    counts = {}

    shed = _safe_get(private, "shed", {})
    if isinstance(shed, dict):
        for item, qty in shed.items():
            counts[item] = counts.get(item, 0) + _int(qty, 0)

    inventories = _safe_get(private, "inventories", [])
    if isinstance(inventories, list):
        for inv in inventories:
            if isinstance(inv, dict):
                for item, qty in inv.items():
                    counts[item] = counts.get(item, 0) + _int(qty, 0)

    return counts


def _plant_ready(tile, day):
    crop = _safe_get(tile, "crop", "WHEAT")
    yield_units = _int(_safe_get(tile, "yield_units", 0), 0)
    planted_day = _int(_safe_get(tile, "planted_day", 0), 0)
    age = max(0, day - planted_day)

    if crop in ONGOING_CROPS:
        return yield_units > 0

    max_day = CROP_MAX_DAY.get(crop, 4)
    max_yield = CROP_MAX_YIELD.get(crop, 4)

    if age >= max_day:
        return True
    if yield_units >= max_yield:
        return True

    return False


def _scan_active_crops(tiles):
    active = {}

    if not _is_sequence(tiles):
        return active

    for row in tiles:
        if not _is_sequence(row):
            continue

        for tile in row:
            if _is_plant(tile):
                crop = _safe_get(tile, "crop", "WHEAT")
                active[crop] = active.get(crop, 0) + 1

    return active


def _crop_cap(crop, planning_worker_count, unlocked_count):
    if crop == "MELON":
        return min(20, 6 + planning_worker_count * 2 + (unlocked_count - 1) * 4)

    if crop == "CARROT":
        return min(16, 4 + planning_worker_count + (unlocked_count - 1) * 3)

    if crop == "WHEAT":
        return min(18, 6 + planning_worker_count + (unlocked_count - 1) * 4)

    return 0


def _choose_target_crop(
    day,
    hour,
    money,
    seeds,
    active_crops,
    market_inventory,
    planning_worker_count,
    unlocked_count,
):
    days_left = max(0, 30 - day)
    if days_left < 4:
        return None

    melon_seeds = _int(_safe_get(seeds, "MELON", 0), 0)
    carrot_seeds = _int(_safe_get(seeds, "CARROT", 0), 0)
    wheat_seeds = _int(_safe_get(seeds, "WHEAT", 0), 0)

    # Use existing seeds first.
    if melon_seeds > 0 and days_left >= MIN_PLANT_DAYS["MELON"]:
        return "MELON"

    if carrot_seeds > 0 and days_left >= MIN_PLANT_DAYS["CARROT"]:
        return "CARROT"

    if wheat_seeds > 0 and days_left >= MIN_PLANT_DAYS["WHEAT"]:
        return "WHEAT"

    # Buy melon if safe.
    if days_left >= MIN_PLANT_DAYS["MELON"] and money >= 200:
        melon_active = active_crops.get("MELON", 0)
        melon_cap = _crop_cap("MELON", planning_worker_count, unlocked_count)
        melon_inventory = _int(_safe_get(market_inventory, "MELON", 10000), 10000)

        if melon_active < melon_cap and melon_inventory <= SELL_SAFE_INVENTORY["MELON"] + 30:
            return "MELON"

    # Buy carrot if safe.
    if days_left >= MIN_PLANT_DAYS["CARROT"] and money >= 100:
        carrot_active = active_crops.get("CARROT", 0)
        carrot_cap = _crop_cap("CARROT", planning_worker_count, unlocked_count)
        carrot_inventory = _int(_safe_get(market_inventory, "CARROT", 10000), 10000)

        if carrot_active < carrot_cap and carrot_inventory <= SELL_SAFE_INVENTORY["CARROT"]:
            return "CARROT"

    # Buy wheat as stable fallback.
    if days_left >= MIN_PLANT_DAYS["WHEAT"]:
        wheat_active = active_crops.get("WHEAT", 0)
        wheat_cap = _crop_cap("WHEAT", planning_worker_count, unlocked_count)

        if wheat_active < wheat_cap:
            return "WHEAT"

    return None


def _generate_tasks(tiles, day, target_crop, plant_slots, new_plant_limits):
    tasks = []
    planted_this_turn = {}

    if not _is_sequence(tiles):
        return tasks

    for y, row in enumerate(tiles):
        if not _is_sequence(row):
            continue

        for x, tile in enumerate(row):
            if tile == "LOCKED":
                continue

            pos = (x, y)

            if tile is None:
                if plant_slots > 0 and target_crop is not None:
                    crop_limit = new_plant_limits.get(target_crop, 999)
                    if planted_this_turn.get(target_crop, 0) < crop_limit:
                        tasks.append({
                            "pos": pos,
                            "type": "PLANT",
                            "priority": 50,
                            "tokens": ["PLANT", target_crop],
                        })
                        planted_this_turn[target_crop] = planted_this_turn.get(target_crop, 0) + 1
                continue

            if _is_weed(tile):
                tasks.append({
                    "pos": pos,
                    "type": "DIG",
                    "priority": 20,
                    "tokens": ["DIG"],
                })
                continue

            if _is_plant(tile):
                if _plant_ready(tile, day):
                    tasks.append({
                        "pos": pos,
                        "type": "HARVEST",
                        "priority": 100,
                        "tokens": ["HARVEST"],
                    })
                elif not bool(_safe_get(tile, "watered_today", False)):
                    tasks.append({
                        "pos": pos,
                        "type": "WATER",
                        "priority": 90,
                        "tokens": ["WATER"],
                    })

                continue

    return tasks


def _default_action(unit_pos, tiles):
    x, y = unit_pos

    if not _in_bounds(tiles, x, y):
        return ["PASS"]

    tile = tiles[y][x]

    if tile == "LOCKED":
        half = max(1, len(tiles) // 2)
        return _step_towards(x, y, half - 1, half - 1)

    return ["PASS"]


# -----------------------------
# Main agent
# -----------------------------

def agent(obs):
    try:
        if not isinstance(obs, dict):
            return _pass()

        player = _int(obs.get("player", 0), 0)
        day = _int(obs.get("day", 0), 0)
        hour = _int(obs.get("hour", 0), 0)

        farms = obs.get("farms", [])
        private = obs.get("private", {})

        if not isinstance(farms, list) or player >= len(farms):
            return _pass()

        me = farms[player]
        if not isinstance(me, dict):
            return _pass()

        money = _float(me.get("money", 0.0), 0.0)
        tiles = me.get("tiles", [])
        farmer = me.get("farmer", [0, 0])
        hands = me.get("hands", [])
        unlocked_quadrants = me.get("unlocked_quadrants", ["NW"])
        hires_today = _int(me.get("hires_today", 0), 0)

        unlocked_count = max(1, len(unlocked_quadrants))
        unlocked_set = set(unlocked_quadrants)

        if not _is_sequence(tiles) or len(farmer) < 2:
            return _pass()

        if not _is_sequence(hands):
            hands = []

        farmer_pos = (farmer[0], farmer[1])
        if not _in_bounds(tiles, farmer_pos[0], farmer_pos[1]):
            return _pass()

        unit_positions = [farmer_pos]
        for hand in hands:
            if _is_sequence(hand) and len(hand) >= 2:
                unit_positions.append((hand[0], hand[1]))
            else:
                unit_positions.append((0, 0))

        current_workers = len(unit_positions)

        planning_workers = current_workers
        if day <= 25 and money >= 1000:
            planning_workers = max(planning_workers, 1 + MAX_HANDS)

        seeds = _safe_get(private, "seeds", {})
        market_info = _safe_get(obs, "market", {})
        market_inventory = _safe_get(market_info, "inventory", {})

        owned_counts = _owned_counts(private)
        owned_total = sum(_int(v, 0) for v in owned_counts.values())
        shed_pressure = owned_total / 100.0

        active_crops = _scan_active_crops(tiles)
        total_crop_count = sum(active_crops.values())
        days_left = max(0, 30 - day)

        # -----------------------------
        # Market buy orders
        # -----------------------------

        buy_orders = []
        money_est = money
        planned_hires = 0

        # Opening hires.
        if day == 0 and hour == 0 and OPENING_HIRE_COUNT > 0:
            for i in range(OPENING_HIRE_COUNT):
                hire_cost = _fib_cost(i)
                if money_est >= hire_cost + 100:
                    buy_orders.append(["HIRE"])
                    money_est -= hire_cost
                    planned_hires += 1
                else:
                    break

        # Opening melon seed purchase.
        if day == 0 and hour == 0 and OPENING_MELON_SEEDS > 0:
            cost = SEED_COST["MELON"] * OPENING_MELON_SEEDS
            if money_est >= cost + SAFE_MONEY_BUFFER:
                buy_orders.append(["BUY_SEED", "MELON", OPENING_MELON_SEEDS])
                money_est -= cost

        target_crop = _choose_target_crop(
            day,
            hour,
            money_est,
            seeds,
            active_crops,
            market_inventory,
            planning_workers,
            unlocked_count,
        )

        target_seeds = _int(_safe_get(seeds, target_crop, 0), 0) if target_crop else 0
        active_target = active_crops.get(target_crop, 0) if target_crop else 0
        cap = _crop_cap(target_crop, planning_workers, unlocked_count) if target_crop else 0

        plant_slots = max(0, min(target_seeds, cap - active_target)) if target_crop else 0
        if hour >= 22:
            plant_slots = 0

        new_plant_limits = MAX_NEW_PLANTS_PER_TURN
        tasks = _generate_tasks(tiles, day, target_crop, plant_slots, new_plant_limits)

        # -----------------------------
        # Worker assignment
        # -----------------------------

        unit_actions = []
        assigned_positions = set()
        assigned_plants = 0

        for unit_idx, unit_pos in enumerate(unit_positions):
            best_task = None
            best_score = -10**9

            preference = (
                ZONE_PREFERENCE[unit_idx]
                if unit_idx < len(ZONE_PREFERENCE)
                else ["NW", "NE", "SW", "SE"]
            )

            for task in tasks:
                task_pos = task["pos"]

                if task_pos in assigned_positions:
                    continue

                if task["type"] == "PLANT" and assigned_plants >= plant_slots:
                    continue

                distance = _manhattan(unit_pos, task_pos)
                task_quadrant = _quadrant(task_pos[0], task_pos[1], tiles)

                zone_bonus = 0
                if task_quadrant in unlocked_set:
                    if len(preference) > 0 and task_quadrant == preference[0]:
                        zone_bonus = 30
                    elif len(preference) > 1 and task_quadrant == preference[1]:
                        zone_bonus = 15

                score = task["priority"] * 100 - distance + zone_bonus

                if score > best_score:
                    best_score = score
                    best_task = task

            if best_task is not None:
                assigned_positions.add(best_task["pos"])

                if best_task["type"] == "PLANT":
                    assigned_plants += 1

                if unit_pos == best_task["pos"]:
                    action = best_task["tokens"]
                else:
                    action = _step_towards(
                        unit_pos[0],
                        unit_pos[1],
                        best_task["pos"][0],
                        best_task["pos"][1],
                    )
            else:
                action = _default_action(unit_pos, tiles)

            unit_actions.append(action)

        # -----------------------------
        # More market buy orders
        # -----------------------------

        # Seed buying.
        if target_crop is not None:
            active_target = active_crops.get(target_crop, 0)
            cap = _crop_cap(target_crop, planning_workers, unlocked_count)
            min_days = MIN_PLANT_DAYS.get(target_crop, 5)

            allow = (days_left >= min_days if hour < 22 else days_left > min_days)

            if allow and active_target < cap:
                need = max(0, cap - active_target - target_seeds)

                if target_crop == "MELON":
                    need = min(SEED_BATCH_MELON, need)
                else:
                    need = min(6, need)

                seed_cost = SEED_COST.get(target_crop, 10) * need

                if need > 0 and money_est >= seed_cost + SAFE_MONEY_BUFFER:
                    buy_orders.append(["BUY_SEED", target_crop, need])
                    money_est -= seed_cost

        # Hire remaining hands.
        if day <= 25 and money_est >= 800:
            already_hired = max(hires_today, planned_hires)

            for i in range(already_hired, MAX_HANDS):
                hire_cost = _fib_cost(i)
                if money_est >= hire_cost + 100:
                    buy_orders.append(["HIRE"])
                    money_est -= hire_cost
                else:
                    break

        # First land expansion.
        if (
            unlocked_count == 1
            and day <= 16
            and total_crop_count >= 6
            and money_est >= 5000
        ):
            buy_orders.append(["BUY_LAND"])
            money_est -= 1000

        # Second land expansion.
        if (
            SECOND_LAND_ENABLED
            and unlocked_count == 2
            and day <= 20
            and total_crop_count >= 10
            and money_est >= 5000
        ):
            buy_orders.append(["BUY_LAND"])
            money_est -= 2000

        # If liquidating or inventory pressure is high, stop buying.
        if shed_pressure >= SHED_PRESSURE_LIMIT or day >= LIQUIDATION_DAY:
            buy_orders = []
        else:
            # Leave at least one market slot for selling.
            buy_orders = buy_orders[:9]

        # -----------------------------
        # Market sell orders
        # -----------------------------

        sell_slots = max(0, 10 - len(buy_orders))
        endgame = day >= LIQUIDATION_DAY or shed_pressure >= SHED_PRESSURE_LIMIT

        sell_candidates = []

        for item in SELLABLE_ITEMS:
            qty = _int(owned_counts.get(item, 0), 0)
            if qty <= 0:
                continue

            item_inventory = _int(_safe_get(market_inventory, item, 10000), 10000)
            safe_inventory = SELL_SAFE_INVENTORY.get(item, 10100)

            sell_qty = 0

            if endgame:
                sell_qty = qty
            else:
                if item_inventory < safe_inventory:
                    room = safe_inventory - item_inventory

                    if item in PREMIUM_ITEMS:
                        max_tranche = 8
                    elif item == "WHEAT":
                        max_tranche = 12
                    else:
                        max_tranche = 6

                    sell_qty = min(qty, max(1, room), max_tranche)
                else:
                    if item in PREMIUM_ITEMS:
                        sell_qty = min(2, qty)
                    else:
                        sell_qty = min(4, qty)

                if shed_pressure >= 0.70:
                    sell_qty = max(sell_qty, min(qty, 4))

            if sell_qty > 0:
                estimated_value = BASE_PRICE.get(item, 1) * sell_qty
                sell_candidates.append((item, sell_qty, estimated_value))

        sell_candidates.sort(key=lambda entry: entry[2], reverse=True)

        market = []
        for item, qty, _ in sell_candidates[:sell_slots]:
            market.append(["SELL", item, qty])

        market.extend(buy_orders)
        market = market[:10]

        farmer_action = unit_actions[0] if unit_actions else ["PASS"]
        hand_actions = unit_actions[1:] if len(unit_actions) > 1 else []

        return {
            "farmer": farmer_action,
            "hands": hand_actions,
            "market": market,
        }

    except Exception:
        return _pass()

